body{margin:0;padding:18px;background:#eef6e6;color:#213;
font-family:system-ui,Arial,sans-serif;font-size:15px;
line-height:1.5}
h1{margin:0 0 12px;font-size:26px}
p{margin:8px 0}
table.werte{width:100%;max-width:520px;border-collapse:collapse;
background:#fff;border-radius:8px;margin:12px 0}
table.werte td{padding:7px 10px;border-bottom:1px solid #e4eede}
td.wert{text-align:right;font-weight:600;white-space:nowrap}
a{color:#2a7}
